-- Texto provisório 0.1, fiel ao documento versionado; registros antigos não recebem aceite presumido.
INSERT INTO versoes_termo (versao,titulo,introducao,topicos,vigente_desde,provisoria) VALUES ('0.1','Termo de consentimento para o tratamento de dados pessoais — Clínica Escola de Psicologia da Faculdade Brasília (versão 0.1, provisória)','Ao se inscrever, você nos passa dados pessoais e dados sobre a sua saúde. A Lei Geral de Proteção de Dados (Lei nº 13.709/2018) chama estes últimos de dados sensíveis. Este termo explica quais dados são esses, para que servem, quem pode vê-los e como você pode desistir.','[{"titulo": "1. O que coletamos", "corpo": "A Faculdade Brasília (FBr), [CNPJ], [ENDEREÇO], é a responsável pelos seus dados. O sistema da Clínica Escola funciona nos servidores da própria FBr.\n\n- **Identificação:** nome, data de nascimento, CPF, RG, estado civil e, se você quiser informar, sexo, profissão e escolaridade.\n- **Endereço e contato:** endereço, bairro, cidade, CEP, e-mail, celular e, se você quiser informar, WhatsApp.\n- **Contato de emergência, se você quiser informar:** nome, grau de parentesco e telefone.\n- **Responsável legal, para menores de 18 anos:** nome, CPF e o documento que comprova a responsabilidade.\n- **Sobre a sua saúde:** o motivo da busca pelo atendimento, como você percebe a urgência e o histórico que quiser contar.\n\nSe você for atendido, o prontuário passa a guardar também a anamnese, os registros de cada sessão e o relatório final."}, {"titulo": "2. Para que usamos", "corpo": "- Fazer a triagem e definir a prioridade do atendimento.\n- Organizar a fila de espera e avisar quando houver vaga.\n- Agendar as sessões, confirmar a presença e emitir declarações de comparecimento.\n- Fazer e guardar o prontuário, como exigem as normas do Conselho Federal de Psicologia.\n- Falar com você, ou com o seu contato de emergência se for preciso. Os avisos do sistema vão para o seu e-mail, e a secretaria pode ligar para o seu celular ou escrever pelo WhatsApp.\n\nUsamos seus dados de saúde com o seu consentimento, dado de forma específica e destacada neste termo (Lei nº 13.709/2018, art. 11, I). Sem esse aceite, não conseguimos registrar a inscrição pelo site, e você pode procurar a secretaria da clínica. Não usamos seus dados para propaganda nem os vendemos ou repassamos a empresas. O uso dos atendimentos em pesquisa depende de outro termo, que você pode aceitar ou não ao assinar o contrato na primeira sessão."}, {"titulo": "3. Quem pode ver", "corpo": "Cada pessoa da equipe vê só o que precisa para o seu trabalho:\n\n- a secretaria vê seus dados de cadastro e de agendamento, mas não o conteúdo clínico;\n- os supervisores e a coordenação veem as respostas da inscrição para fazer a triagem;\n- o prontuário só pode ser aberto pelo estagiário responsável pelo seu atendimento, pelo supervisor dele e pela coordenação.\n\nTodo acesso ao prontuário fica registrado, com quem acessou e quando. Seus dados só são passados a outras pessoas ou órgãos quando a lei ou uma ordem judicial obrigar.\n\n**Como protegemos:**\n\n- As informações sobre a sua saúde ficam guardadas cifradas, isto é, embaralhadas de um jeito que só o sistema consegue ler.\n- O acesso ao sistema exige login de cada pessoa da equipe, e o prontuário fica restrito a quem cuida do seu atendimento.\n- Todo o tráfego entre o seu aparelho e o sistema é protegido (HTTPS).\n- O sistema faz uma cópia de segurança cifrada dos dados por dia, guardada pela FBr fora do servidor principal.\n- A equipe segue o sigilo profissional do Código de Ética do Psicólogo."}, {"titulo": "4. Por quanto tempo guardamos", "corpo": "- Se você for atendido, o prontuário e os registros do atendimento são guardados por pelo menos 5 anos depois do fim do acompanhamento, como exigem as Resoluções nº 1/2009 e nº 5/2025 do Conselho Federal de Psicologia ([RF65](../requisitos/funcionais.md#rf65)). Depois desse prazo, os dados só são eliminados ou tornados anônimos com a autorização do psicólogo responsável técnico.\n- Se a sua inscrição não chegar a virar atendimento, os dados ficam guardados por [PRAZO PARA INSCRIÇÕES NÃO ATENDIDAS] e depois são eliminados."}, {"titulo": "5. Seus direitos e como desistir", "corpo": "Você pode pedir, a qualquer momento e sem custo:\n\n- a confirmação de que tratamos seus dados e o acesso a eles;\n- a correção de dados incompletos, errados ou desatualizados;\n- a informação sobre com quem seus dados foram compartilhados;\n- a revogação deste consentimento.\n\n**Como desistir (revogar o consentimento).** Peça na secretaria da Clínica Escola, pessoalmente com um documento, ou pelo [E-MAIL PARA PEDIDOS SOBRE DADOS]. Antes de registrar o pedido, confirmamos que é você, ou o seu responsável legal, quem está pedindo.\n\n**O que acontece depois:**\n\n- Se você ainda estiver na fila de espera, a sua inscrição sai da fila.\n- Se você estiver em atendimento, não marcamos novas sessões, e o seu supervisor e a coordenação combinam com você o encerramento do acompanhamento.\n- Em qualquer caso, paramos de enviar lembretes e avisos e não usamos mais seus dados para nada novo.\n- O que já foi registrado, como a inscrição e o prontuário, não é apagado: a lei obriga a guardar esses registros pelo prazo mínimo de 5 anos (Lei nº 13.709/2018, art. 16, I, e Resolução CFP nº 1/2009), com o mesmo acesso restrito.\n- Se quiser voltar a ser atendido depois, é preciso fazer uma nova inscrição e aceitar o termo de novo.\n\n**Contato.** Dúvidas sobre seus dados: [E-MAIL PARA PEDIDOS SOBRE DADOS] ou a secretaria da Clínica Escola, [TELEFONE DA CLÍNICA]. [SE HOUVER: Encarregado de dados da FBr: NOME E E-MAIL.]"}]'::jsonb,'2026-11-06T00:00:00-03:00',true);
